import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

path = 'budget.xlsx'
z = zipfile.ZipFile(path)
print("Archive entries:", z.namelist())

wb = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
rel_map = {}
for rel in rels:
    rel_map[rel.get('Id')] = rel.get('Target')

shared = {}
if 'xl/sharedStrings.xml' in z.namelist():
    sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for i, si in enumerate(sst.findall('m:si', NS)):
        text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        shared[i] = text

sheets = wb.find('m:sheets', NS)
for sheet in sheets.findall('m:sheet', NS):
    name = sheet.get('name')
    rid = sheet.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')
    target = rel_map[rid]
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    ws = ET.fromstring(z.read(target))
    print(f"\n=== Sheet: {name} ===")
    for row in ws.findall('.//m:row', NS):
        vals = []
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            t = c.get('t')
            v = c.find('m:v', NS)
            if v is None:
                val = ''
            elif t == 's':
                val = shared[int(v.text)]
            elif t == 'inlineStr':
                is_el = c.find('m:is', NS)
                val = ''.join(x.text or '' for x in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            else:
                val = v.text
            vals.append(f"{ref}={val}")
        print(' | '.join(vals))

